-- =====================================================================================================
-- ResolveAI application database: schema and test data. Engine: SQLite 3 with FTS5 (NOT SQL Server).
--
-- SQLite has no CREATE DATABASE: the database is the file you load this script into.
-- You only need this script for a database with sample activity already in it. The app creates and
-- seeds its own database on first start, and leaves a database that already has incidents alone.
--
-- Load into a NEW file (loading into an existing database fails with "table already exists"):
--
--   Python:   python -c "import sqlite3; c = sqlite3.connect('data/resolveai-test.db'); c.executescript(open('database/resolveai.sql', encoding='utf-8').read())"
--   sqlite3:  sqlite3 -bail data/resolveai-test.db ".read database/resolveai.sql"
--
-- Then point the app at it. PowerShell:
--
--   $env:DB_PATH = 'data/resolveai-test.db'; dotnet run --project src/ResolveAI.App
--
-- Everything here is synthetic. Fake secrets and the prompt-injection line in log_events are deliberate:
-- they exercise redaction and injection handling. Settings > Reset demo data clears Part 3.
--
-- Generated from a database the app built itself, so IDs match the recorded fixtures. Schema changes
-- belong in src/ResolveAI.App/Data/Migrations, and this file must then be regenerated.
-- =====================================================================================================

PRAGMA foreign_keys = ON;
BEGIN TRANSACTION;

-- ----- Part 1: tables, indexes and triggers ------------------------------------------------------

CREATE TABLE _migrations (name TEXT PRIMARY KEY, applied_at TEXT NOT NULL);

CREATE TABLE incidents (
  id              TEXT PRIMARY KEY,
  key             TEXT NOT NULL UNIQUE,
  title           TEXT NOT NULL,
  service_name    TEXT NOT NULL,
  severity        TEXT NOT NULL CHECK (severity IN ('SEV-1','SEV-2','SEV-3','SEV-4')),
  status          TEXT NOT NULL CHECK (status IN ('open','investigating','mitigated','resolved')),
  environment     TEXT NOT NULL,
  started_at      TEXT NOT NULL,
  detected_at     TEXT NOT NULL,
  resolved_at     TEXT,
  description     TEXT NOT NULL,
  impact_summary  TEXT NOT NULL,
  created_at      TEXT NOT NULL
);

CREATE TABLE log_events (
  id               TEXT PRIMARY KEY,
  incident_id      TEXT REFERENCES incidents(id) ON DELETE SET NULL,
  timestamp        TEXT NOT NULL,
  service_name     TEXT NOT NULL,
  level            TEXT NOT NULL,
  message          TEXT NOT NULL,
  error_signature  TEXT,
  trace_id         TEXT,
  source           TEXT NOT NULL
);

CREATE TABLE deployments (
  id              TEXT PRIMARY KEY,
  service_name    TEXT NOT NULL,
  environment     TEXT NOT NULL,
  version         TEXT NOT NULL,
  deployed_at     TEXT NOT NULL,
  change_summary  TEXT NOT NULL,
  commit_ref      TEXT,
  incident_id     TEXT REFERENCES incidents(id) ON DELETE SET NULL
);

CREATE TABLE metric_snapshots (
  id           TEXT PRIMARY KEY,
  incident_id  TEXT NOT NULL REFERENCES incidents(id) ON DELETE CASCADE,
  name         TEXT NOT NULL,
  unit         TEXT NOT NULL,
  baseline     REAL NOT NULL,
  peak         REAL NOT NULL,
  observed_at  TEXT NOT NULL
);

CREATE TABLE timeline_events (
  id           TEXT PRIMARY KEY,
  incident_id  TEXT NOT NULL REFERENCES incidents(id) ON DELETE CASCADE,
  timestamp    TEXT NOT NULL,
  kind         TEXT NOT NULL,
  description  TEXT NOT NULL
);

CREATE TABLE knowledge_documents (
  id            TEXT PRIMARY KEY,
  title         TEXT NOT NULL,
  doc_type      TEXT NOT NULL CHECK (doc_type IN ('runbook','rca','guide')),
  service_name  TEXT,
  body          TEXT NOT NULL,
  source_uri    TEXT,
  tags          TEXT NOT NULL DEFAULT '[]',
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
);

CREATE VIRTUAL TABLE knowledge_fts USING fts5(id UNINDEXED, title, body, tags);

CREATE TABLE historical_incidents (
  id               TEXT PRIMARY KEY,
  key              TEXT NOT NULL UNIQUE,
  title            TEXT NOT NULL,
  service_name     TEXT NOT NULL,
  symptoms         TEXT NOT NULL,
  root_cause       TEXT NOT NULL,
  resolution       TEXT NOT NULL,
  rca_document_id  TEXT REFERENCES knowledge_documents(id) ON DELETE SET NULL,
  resolved_at      TEXT NOT NULL,
  tags             TEXT NOT NULL DEFAULT '[]'
);

CREATE VIRTUAL TABLE historical_fts USING fts5(id UNINDEXED, title, service_name, symptoms, root_cause, resolution, tags);

CREATE TABLE investigations (
  id                     TEXT PRIMARY KEY,
  incident_id            TEXT NOT NULL REFERENCES incidents(id) ON DELETE CASCADE,
  status                 TEXT NOT NULL CHECK (status IN ('queued','running','completed','failed')),
  stage                  TEXT,
  question               TEXT,
  llm_mode               TEXT NOT NULL,
  evidence_packet        TEXT,
  model_name             TEXT,
  prompt_version         TEXT NOT NULL,
  summary                TEXT,
  insufficient_evidence  INTEGER NOT NULL DEFAULT 0,
  limitations            TEXT NOT NULL DEFAULT '[]',
  validation_issues      TEXT NOT NULL DEFAULT '[]',
  usage                  TEXT,
  started_at             TEXT NOT NULL,
  completed_at           TEXT,
  error_message          TEXT
, trace TEXT NOT NULL DEFAULT '[]');

CREATE TABLE hypotheses (
  id                  TEXT PRIMARY KEY,
  investigation_id    TEXT NOT NULL REFERENCES investigations(id) ON DELETE CASCADE,
  rank                INTEGER NOT NULL,
  title               TEXT NOT NULL,
  explanation         TEXT NOT NULL,
  confidence          TEXT NOT NULL CHECK (confidence IN ('low','medium','high')),
  score               REAL NOT NULL,
  speculative         INTEGER NOT NULL DEFAULT 0,
  counter_evidence    TEXT NOT NULL DEFAULT '[]',
  unknowns            TEXT NOT NULL DEFAULT '[]',
  recommended_checks  TEXT NOT NULL DEFAULT '[]'
);

CREATE TABLE evidence_links (
  hypothesis_id  TEXT NOT NULL REFERENCES hypotheses(id) ON DELETE CASCADE,
  evidence_ref   TEXT NOT NULL,
  position       INTEGER NOT NULL,
  PRIMARY KEY (hypothesis_id, evidence_ref)
);

CREATE TABLE investigation_similar_incidents (
  investigation_id        TEXT NOT NULL REFERENCES investigations(id) ON DELETE CASCADE,
  historical_incident_id  TEXT NOT NULL REFERENCES historical_incidents(id) ON DELETE CASCADE,
  rank                    INTEGER NOT NULL,
  match_score             REAL NOT NULL,
  matched_terms           TEXT NOT NULL DEFAULT '[]',
  similarity_reason       TEXT NOT NULL,
  PRIMARY KEY (investigation_id, historical_incident_id)
);

CREATE TABLE rca_drafts (
  id                    TEXT PRIMARY KEY,
  incident_id           TEXT NOT NULL REFERENCES incidents(id) ON DELETE CASCADE,
  investigation_id      TEXT NOT NULL REFERENCES investigations(id) ON DELETE CASCADE,
  version               INTEGER NOT NULL,
  status                TEXT NOT NULL CHECK (status IN ('draft','reviewed')),
  impact                TEXT NOT NULL,
  timeline              TEXT NOT NULL DEFAULT '[]',
  root_cause            TEXT NOT NULL,
  contributing_factors  TEXT NOT NULL DEFAULT '[]',
  resolution_steps      TEXT NOT NULL DEFAULT '[]',
  prevention_actions    TEXT NOT NULL DEFAULT '[]',
  evidence_ids          TEXT NOT NULL DEFAULT '[]',
  generated_at          TEXT NOT NULL,
  updated_at            TEXT NOT NULL, validation_issues TEXT NOT NULL DEFAULT '[]', llm_mode TEXT NOT NULL DEFAULT 'recorded',
  UNIQUE (incident_id, version)
);

CREATE TABLE feedback (
  id                   TEXT PRIMARY KEY,
  investigation_id     TEXT NOT NULL REFERENCES investigations(id) ON DELETE CASCADE,
  hypothesis_id        TEXT REFERENCES hypotheses(id) ON DELETE CASCADE,
  helpful              INTEGER,
  comment              TEXT,
  verified_root_cause  TEXT,
  created_at           TEXT NOT NULL
);

CREATE TABLE tool_calls (
  id               TEXT PRIMARY KEY,
  investigation_id TEXT NOT NULL REFERENCES investigations(id) ON DELETE CASCADE,
  seq              INTEGER NOT NULL,
  phase            TEXT NOT NULL CHECK (phase IN ('baseline', 'follow_up')),
  system           TEXT NOT NULL,
  server           TEXT NOT NULL,
  tool             TEXT NOT NULL,
  args             TEXT NOT NULL,
  ok               INTEGER NOT NULL,
  summary          TEXT NOT NULL,
  rows             TEXT NOT NULL,
  truncated        INTEGER NOT NULL,
  duration_ms      INTEGER NOT NULL,
  started_at       TEXT NOT NULL,
  UNIQUE (investigation_id, seq)
);

CREATE INDEX idx_incidents_status_started ON incidents(status, started_at);

CREATE INDEX idx_log_events_incident_ts ON log_events(incident_id, timestamp);

CREATE INDEX idx_log_events_service_ts ON log_events(service_name, timestamp);

CREATE INDEX idx_deployments_service_deployed ON deployments(service_name, deployed_at);

CREATE INDEX idx_metric_snapshots_incident ON metric_snapshots(incident_id);

CREATE INDEX idx_timeline_events_incident_ts ON timeline_events(incident_id, timestamp);

CREATE INDEX idx_investigations_incident ON investigations(incident_id, started_at);

CREATE INDEX idx_hypotheses_investigation ON hypotheses(investigation_id, rank);

CREATE INDEX idx_feedback_investigation ON feedback(investigation_id);

CREATE INDEX idx_investigations_mode_started ON investigations(llm_mode, started_at);

CREATE TRIGGER log_events_immutable BEFORE UPDATE ON log_events
BEGIN
  SELECT RAISE(ABORT, 'log_events are immutable');
END;

-- ----- Migration records. The app re-runs any migration not listed here and would fail on it. ----

