-- knowledge_documents: 4 row(s)
INSERT INTO "knowledge_documents" ("id", "title", "doc_type", "service_name", "body", "source_uri", "tags", "created_at", "updated_at") VALUES ('fd3a645b-e7fe-5125-a3bf-ae6f4088390e', 'Runbook: payment-api database connectivity', 'runbook', 'payment-api', 'When payment-api reports database connection timeouts: 1) Check DB connection pool utilization (in_use vs max) on payment-api pods. 2) Check database availability, CPU and active connections on payments-db. 3) Compare the effective max connection / pool size configuration with the last healthy deployment. 4) Review differences from the last healthy deployment before rolling back.', NULL, '["database","connection pool","timeout","payment-api"]', '2026-11-02T06:53:34.390Z', '2026-11-02T06:53:34.390Z');
INSERT INTO "knowledge_documents" ("id", "title", "doc_type", "service_name", "body", "source_uri", "tags", "created_at", "updated_at") VALUES ('43b4a932-4e32-51ed-a46e-9291fff48a31', 'RCA: INC-0881 Payment API connection pool exhaustion', 'rca', 'payment-api', 'Impact: 41 minutes of elevated 500s on payment-api. Root cause: a configuration change reduced the database connection pool max from 100 to 10; under normal peak load requests queued for connections and timed out. Detection was delayed because the DB itself looked healthy. Resolution: validated config and restored the last-known-good pool size. Prevention: config schema validation for pool size, alert on pool saturation.', NULL, '["connection pool","config change","postgres"]', '2026-11-02T06:53:34.390Z', '2026-11-02T06:53:34.390Z');
INSERT INTO "knowledge_documents" ("id", "title", "doc_type", "service_name", "body", "source_uri", "tags", "created_at", "updated_at") VALUES ('5dd7447a-c19a-58a7-a934-c37b10ad200e', 'Runbook: notification-service SMTP delivery', 'runbook', 'notification-service', 'If SMTP relay returns 421 rate limited: check sending volume vs provider quota, check whether a bulk campaign is running, enable the secondary relay, and pause non-critical email categories.', NULL, '["smtp","email","rate limit"]', '2026-11-02T06:53:34.390Z', '2026-11-02T06:53:34.390Z');
INSERT INTO "knowledge_documents" ("id", "title", "doc_type", "service_name", "body", "source_uri", "tags", "created_at", "updated_at") VALUES ('8a300585-3caf-50bc-a29f-643d5460a0e4', 'Guide: first 15 minutes of an incident', 'guide', NULL, 'Establish impact, check recent deployments and config changes, look for matching past incidents, assign an incident commander, and communicate status every 15 minutes.', NULL, '["oncall","triage"]', '2026-11-02T06:53:34.390Z', '2026-11-02T06:53:34.390Z');

-- knowledge_fts: 4 row(s)
INSERT INTO "knowledge_fts" ("id", "title", "body", "tags") VALUES ('fd3a645b-e7fe-5125-a3bf-ae6f4088390e', 'Runbook: payment-api database connectivity', 'When payment-api reports database connection timeouts: 1) Check DB connection pool utilization (in_use vs max) on payment-api pods. 2) Check database availability, CPU and active connections on payments-db. 3) Compare the effective max connection / pool size configuration with the last healthy deployment. 4) Review differences from the last healthy deployment before rolling back.', 'database connection pool timeout payment-api');
INSERT INTO "knowledge_fts" ("id", "title", "body", "tags") VALUES ('43b4a932-4e32-51ed-a46e-9291fff48a31', 'RCA: INC-0881 Payment API connection pool exhaustion', 'Impact: 41 minutes of elevated 500s on payment-api. Root cause: a configuration change reduced the database connection pool max from 100 to 10; under normal peak load requests queued for connections and timed out. Detection was delayed because the DB itself looked healthy. Resolution: validated config and restored the last-known-good pool size. Prevention: config schema validation for pool size, alert on pool saturation.', 'connection pool config change postgres');
INSERT INTO "knowledge_fts" ("id", "title", "body", "tags") VALUES ('5dd7447a-c19a-58a7-a934-c37b10ad200e', 'Runbook: notification-service SMTP delivery', 'If SMTP relay returns 421 rate limited: check sending volume vs provider quota, check whether a bulk campaign is running, enable the secondary relay, and pause non-critical email categories.', 'smtp email rate limit');
INSERT INTO "knowledge_fts" ("id", "title", "body", "tags") VALUES ('8a300585-3caf-50bc-a29f-643d5460a0e4', 'Guide: first 15 minutes of an incident', 'Establish impact, check recent deployments and config changes, look for matching past incidents, assign an incident commander, and communicate status every 15 minutes.', 'oncall triage');

