INSERT INTO "investigations" ("id", "incident_id", "status", "stage", "question", "llm_mode", "evidence_packet", "model_name", "prompt_version", "summary", "insufficient_evidence", "limitations", "validation_issues", "usage", "started_at", "completed_at", "error_message", "trace") VALUES ('3d0ac2cf-7265-4228-8169-2b54160cb14c', 'd9202e95-90a2-54a9-aead-bfb7159ef028', 'completed', NULL, 'Why did payment-api start returning 500s after 10:00 UTC?', 'recorded', '{"incident":{"key":"INC-1042","title":"Payment API elevated 500 errors","service":"payment-api","severity":"SEV-1","environment":"production","started_at":"2026-10-27T10:03:50Z","detected_at":"2026-10-27T10:05:00Z","description":"Payment API began returning HTTP 500 errors to checkout shortly after 10:00 UTC. Card authorisations are failing for a large share of requests.","impact_summary":"~28% of payment requests failing; checkout conversion down sharply for all regions."},"question":"Why did payment-api start returning 500s after 10:00 UTC?","items":[{"id":"hist:2c1179b6-fb72-5098-af74-3c0a40fc270d","type":"historical_incident","timestamp":"2025-11-02T08:10:00Z","source":"incident-history","excerpt":"INC-0702 Payment API TLS certificate expired (payment-api). Symptoms: Handshake failures to card processor; HTTP 502 errors. Root cause: Expired client certificate for processor mTLS. Resolution: Rotated certificate; added expiry monitoring."},{"id":"hist:188d7706-a816-55d4-a433-64a470e4e2d9","type":"historical_incident","timestamp":"2026-03-14T12:30:00Z","source":"incident-history","excerpt":"INC-0881 Payment API connection pool exhaustion (payment-api). Symptoms: HTTP 500 errors and database connection timeouts after a deployment; database CPU and connections normal. Root cause: Incorrect max connection setting after config change. Resolution: Validated config and restored last-known-good setting."},{"id":"dep:f672d304-8bfa-54b4-a2ea-3fd98d4ce7be","type":"deployment","timestamp":"2026-10-25T16:20:00Z","source":"deploys/payment-api","excerpt":"payment-api v2.8.0 deployed to production: Add idempotency keys to refund endpoint (commit a41c9e2)"},{"id":"dep:049665c8-c502-5526-a973-75747c984147","type":"deployment","timestamp":"2026-10-27T09:30:00Z","source":"deploys/checkout-web","excerpt":"checkout-web v5.2.0 deployed to production: New address autocomplete widget (commit e19a7c4)"},{"id":"log:6a03613a-d255-5f7a-a132-5381fa642c18","type":"log","timestamp":"2026-10-27T09:58:30Z","source":"app/payment-api","excerpt":"INFO payment-api: health check ok; db pool in_use=6 max=100"},{"id":"tl:5bda604c-80f5-59dd-aa7b-fcfcb939cb98","type":"timeline","timestamp":"2026-10-27T10:00:00Z","source":"deployment","excerpt":"payment-api v2.8.1 rollout started"},{"id":"log:4d9d9535-5771-5db7-af2c-3b35c1bafd08","type":"log","timestamp":"2026-10-27T10:00:00Z","source":"deploy-agent/payment-api","excerpt":"INFO deploy-agent: payment-api v2.8.1 rollout started (3/3 pods)"},{"id":"dep:2166be3a-1fba-50c5-a9aa-a4ac50847adb","type":"deployment","timestamp":"2026-10-27T10:00:00Z","source":"deploys/payment-api","excerpt":"payment-api v2.8.1 deployed to production: Database client configuration updated (connection pool settings moved to db-client.yaml) (commit 7d03b1f)"},{"id":"log:7297f7a6-0ec0-5e8a-a78f-3f697ded5baa","type":"log","timestamp":"2026-10-27T10:00:41Z","source":"app/payment-api","excerpt":"INFO payment-api: db client config loaded from db-client.yaml: pool.max=20 pool.acquireTimeoutMs=5000"},{"id":"tl:8bb123fa-8cf0-5570-ada3-ebd3cafd09f9","type":"timeline","timestamp":"2026-10-27T10:03:50Z","source":"symptom","excerpt":"First HTTP 500 responses returned to checkout"},{"id":"log:1c602ba5-cdae-5d2b-a94b-a9a58b8c5422","type":"log","timestamp":"2026-10-27T10:03:55Z","source":"app/payment-api","excerpt":"WARN payment-api: db pool exhausted; in_use=20 max=20 waiting_requests=14 [signature=db_pool_exhausted]"},{"id":"log:7ef1ad9b-c7cd-5c68-ab5a-85252c539ef5","type":"log","timestamp":"2026-10-27T10:04:12Z","source":"app/payment-api","excerpt":"ERROR payment-api: database connection acquisition timed out; request_id=req-781 [signature=db_conn_acquire_timeout]","occurrences":3},{"id":"log:a56622d6-c4a1-5385-a1c4-600dee2ce9f3","type":"log","timestamp":"2026-10-27T10:04:20Z","source":"app/payment-api","excerpt":"ERROR payment-api: upstream request failed with HTTP 500 [signature=http_500_upstream]","occurrences":2},{"id":"tl:2b46c01b-4e6e-573d-a0ee-2828f65c2af0","type":"timeline","timestamp":"2026-10-27T10:05:00Z","source":"alert","excerpt":"Alert fired: payment-api 5xx rate above 5% for 1 minute"},{"id":"log:5e90e17e-7574-5d6b-aa8f-e4c75f56b5f1","type":"log","timestamp":"2026-10-27T10:06:40Z","source":"app/payment-api","excerpt":"ERROR payment-api: charge retry failed for merchant m-2231; header Authorization: Bearer [REDACTED]; HTTP 500 [signature=http_500_upstream]"},{"id":"tl:a57f0077-b88d-5a73-a7b7-f95c93b3586b","type":"timeline","timestamp":"2026-10-27T10:07:00Z","source":"response","excerpt":"On-call engineer acknowledged the page"},{"id":"log:80c5db1c-5d2d-5814-a9b3-5e0cc2919275","type":"log","timestamp":"2026-10-27T10:07:10Z","source":"postgres/payments-db","excerpt":"INFO payments-db: active_connections=20 max_connections=500 cpu=22% replication_lag=0s"},{"id":"met:4fe002f1-b678-58cc-a225-6f0c5bcf8095","type":"metric","timestamp":"2026-10-27T10:10:00Z","source":"metrics","excerpt":"DB pool connections in use: baseline 6 connections → peak 20 connections"},{"id":"met:d720dddd-07c8-59fa-a0b2-84fb5309802e","type":"metric","timestamp":"2026-10-27T10:10:00Z","source":"metrics","excerpt":"Database CPU: baseline 21 % → peak 23 %"},{"id":"met:2084c2c1-62ac-5fab-a760-fdd82933b7ba","type":"metric","timestamp":"2026-10-27T10:10:00Z","source":"metrics","excerpt":"HTTP 500 rate: baseline 0.2 % → peak 28 %"},{"id":"met:58d06a16-302d-5a6c-a52f-160d1c0a8d5d","type":"metric","timestamp":"2026-10-27T10:10:00Z","source":"metrics","excerpt":"Latency p95: baseline 180 ms → peak 2400 ms"},{"id":"tl:90831ecf-7cb0-5cae-a7ba-741db105e791","type":"timeline","timestamp":"2026-10-27T10:12:00Z","source":"response","excerpt":"Incident declared SEV-1; incident commander assigned"},{"id":"doc:fd3a645b-e7fe-5125-a3bf-ae6f4088390e","type":"runbook","timestamp":null,"source":"runbook","excerpt":"Runbook: payment-api database connectivity: When payment-api reports database connection timeouts: 1) Check DB connection pool utilization (in_use vs max) on payment-api pods. 2) Check database availability, CPU and active connections on payments-db. 3) Compare the effective max connection / pool size configuration with the last healthy deployment. 4) Review differences from the last healthy deployment before rolling back."},{"id":"doc:8a300585-3caf-50bc-a29f-643d5460a0e4","type":"runbook","timestamp":null,"source":"guide","excerpt":"Guide: first 15 minutes of an incident: Establish impact, check recent deployments and config changes, look for matching past incidents, assign an incident commander, and communicate status every 15 minutes."},{"id":"mcp:1","type":"tool_result","timestamp":null,"source":"files: files_search(root=payment-api, phrase=ERROR, from=2026-10-27T09:33:50Z, to=2026-10-27T11:05:00Z, max_matches=30)","excerpt":"6 line(s) containing \"ERROR\" in logs/payment-api (2 file(s) scanned).\nfile=logs/payment-api/app.log line=6 time=2026-10-27T10:04:12.403Z text=2026-10-27T10:04:12.403Z ERROR payment-api database connection acquisition timed out after 5000ms; request_id=req-781\nfile=logs/payment-api/app.log line=7 time=2026-10-27T10:04:15.118Z text=2026-10-27T10:04:15.118Z ERROR payment-api database connection acquisition timed out after 5000ms; request_id=req-782\nfile=logs/payment-api/app.log line=8 time=2026-10-27T10:04:20.640Z text=2026-10-27T10:04:20.640Z ERROR payment-api upstream request failed with HTTP 500\nfile=logs/payment-api/app.log line=9 time=2026-10-27T10:05:02.009Z text=2026-10-27T10:05:02.009Z ERROR payment-api database connectio