OR, from=2026-10-27T12:50:00Z, to=2026-10-27T14:45:00Z, max_matches=30)","excerpt":"No lines containing \"ERROR\" in logs/search-api (1 file(s) scanned)."},{"id":"mcp:2","type":"tool_result","timestamp":null,"source":"files: files_search(root=search-api, phrase=WARN, from=2026-10-27T12:50:00Z, to=2026-10-27T14:45:00Z, max_matches=15)","excerpt":"No lines containing \"WARN\" in logs/search-api (1 file(s) scanned)."},{"id":"mcp:3","type":"tool_result","timestamp":null,"source":"deploys: deploys_recent(service=search-api, from=2026-10-26T15:45:00Z, to=2026-10-27T14:45:00Z)","excerpt":"No deployments or commits for search-api in that window."}],"similar_candidates":[],"redactions":0,"truncated":false}', NULL, 'inv-2026-10-28.1', 'The packet for INC-1043 contains no error signatures, recent search-api deployments or significant metric changes. There is insufficient evidence to propose a root cause.', 1, '["Recorded/offline mode: this analysis was produced by deterministic rules, not by a live model call.","Collect error logs, deployment history and metrics for the affected window, then run the investigation again."]', '[]', NULL, '2026-11-02T06:53:38.496Z', '2026-11-02T06:53:39.733Z', NULL, '[{"stage":"Gather evidence","started_at":"2026-11-02T06:53:38.499Z","duration_ms":1,"details":{"logs":1,"error_signals":0,"deployments":0,"metrics":1,"timeline_events":2,"runbooks":1}},{"stage":"Search incident history","started_at":"2026-11-02T06:53:38.501Z","duration_ms":0,"details":{"candidates":0,"top_match":"none"}},{"stage":"Baseline checks (MCP)","started_at":"2026-11-02T06:53:38.503Z","duration_ms":18,"details":{"calls":3,"failed":0,"files":2,"deploys":1,"systems_off":"database"}},{"stage":"Build evidence packet","started_at":"2026-11-02T06:53:38.523Z","duration_ms":0,"details":{"items":8,"characters":2298,"redactions":0,"truncated":false}},{"stage":"Follow-up checks (recorded)","started_at":"2026-11-02T06:53:38.527Z","duration_ms":0,"details":{"calls":0,"limit":8,"refused":0