-- hypotheses: 6 row(s)
INSERT INTO "hypotheses" ("id", "investigation_id", "rank", "title", "explanation", "confidence", "score", "speculative", "counter_evidence", "unknowns", "recommended_checks") VALUES ('473d03bf-4730-43e2-9d60-49b8ef99df21', '3d0ac2cf-7265-4228-8169-2b54160cb14c', 1, 'v2.8.1 config change reduced the DB connection pool (100 → 20), exhausting it under normal load', 'The v2.8.1 deployment changed database client configuration. After rollout the service loaded pool.max=20, whereas the pre-deploy health check showed max=100. Within four minutes the pool was full (in_use=20, 14 waiting) and connection acquisition began timing out, which surfaced as HTTP 500s. Pool connections in use rose to exactly the new limit, while the database reported ample capacity.', 'high', 10.0, 0, '["Errors started ~4 minutes after rollout began; a traffic ramp would explain the lag but traffic volume is not in the packet."]', '["Whether pool.max=20 was intentional in the v2.8.1 change","Request volume compared with the same time on previous days"]', '[{"step":"Compare the effective pool.max and acquireTimeoutMs between v2.8.0 and v2.8.1 (db-client.yaml and the previous config source).","why":"Confirms whether the release changed the pool size rather than load increasing.","expected_signal":"v2.8.0 resolved pool.max to 100 (or similar); v2.8.1 resolves to 20."},{"step":"Check the pool utilisation dashboard for every payment-api pod since 10:00.","why":"Pool exhaustion should be visible on all pods running v2.8.1.","expected_signal":"in_use pinned at max with a growing wait queue on all pods."},{"step":"Confirm payments-db has connection and CPU headroom for the full window.","why":"Rules out the database itself as the bottleneck.","expected_signal":"Active connections far below max_connections; CPU flat."}]');
INSERT INTO "hypotheses" ("id", "investigation_id", "rank", "title", "explanation", "confidence", "score", "speculative", "counter_evidence", "unknowns", "recommended_checks") VALUES ('6becac22-0280-4b74-93fe-3841cb4269b7', '3d0ac2cf-7265-4228-8169-2b54160cb14c', 2, 'Load increase from the checkout-web v5.2.0 release', 'checkout-web deployed v5.2.0 at 09:30. If the new address autocomplete widget issued extra payment calls, increased load could exhaust the pool.', 'low', 2.0, 0, '["The release was 34 minutes before errors began and its change summary concerns address autocomplete, not payments."]', '["Payment request rate from checkout-web before and after 09:30"]', '[{"step":"Compare payment-api request rate from checkout-web before and after 09:30.","why":"Distinguishes a load increase from a capacity reduction.","expected_signal":"Flat request rate, which would rule this out."}]');
INSERT INTO "hypotheses" ("id", "investigation_id", "rank", "title", "explanation", "confidence", "score", "speculative", "counter_evidence", "unknowns", "recommended_checks") VALUES ('57f042b2-5147-42dc-af64-759a9efcb864', '3d0ac2cf-7265-4228-8169-2b54160cb14c', 3, 'payments-db unavailable or overloaded', 'Connection acquisition timeouts can be caused by a database that is slow to accept connections. The packet contains timeouts but no database-side errors.', 'low', 1.0, 0, '["payments-db reported active_connections=20 of max_connections=500, CPU 22% and no replication lag at 10:07.","Database CPU stayed flat (21% → 23%) through the incident."]', '["Database slow-query log for the window"]', '[{"step":"Review payments-db slow-query and connection logs from 10:00 to 10:15.","why":"A database-side cause would show refused or slow connection handshakes.","expected_signal":"No refused connections or slow handshakes, which would rule this out."}]');
INSERT INTO "hypotheses" ("id", "investigation_id", "rank", "title", "explanation", "confidence", "score", "speculative", "counter_evidence", "unknowns", "recommended_checks") VALUES ('3ef12cbe-9742-4f3b-8084-6a5565154848', '3e01b52c-23e6-4474-872f-0609ce637f18', 1, 'smtp 421 rate limited is the primary failure mode', 'The most frequent error signature in the window is "smtp_421_rate_limited" (3 occurrences). Related metrics moved sharply over the same period.', 'medium', 8.0, 0, '[]', '["What changed to trigger this failure mode"]', '[{"step":"Find when \"smtp_421_rate_limited\" first appeared and whether it correlates with traffic, a dependency or a configuration change.","why":"Establishes the trigger rather than the symptom.","expected_signal":"A clear onset time that lines up with a specific change."}]');
INSERT INTO "hypotheses" ("id", "investigation_id", "rank", "title", "explanation", "confidence", "score", "speculative", "counter_evidence", "unknowns", "recommended_checks") VALUES ('f2ccf2d5-daac-454d-a829-e4fc96402922', '3e01b52c-23e6-4474-872f-0609ce637f18', 2, 'Recurrence of a past incident (INC-0655)', 'A previous incident on notification-service had matching symptoms. INC-0655 Email backlog after SMTP provider throttling (notification-service). Symptoms: Email queue depth growing; SMTP 421 rate limited responses. Root cause: Marketing bulk send exhausted shared SMTP quota. Resolution: Moved transactional email to a dedicated relay; paused bulk campaign.', 'low', 4.0, 0, '[]', '["Whether the previous fix is still in place"]', '[{"step":"Check whether the previous incident''s trigger is present again.","why":"Past root causes often recur when the fix was partial.","expected_signal":"The same trigger condition visible in the current window."}]');
INSERT INTO "hypotheses" ("id", "investigation_id", "rank", "title", "explanation", "confidence", "score", "speculative", "counter_evidence", "unknowns", "recommended_checks") VALUES ('6923db66-ffdf-49e1-a754-d575da78295c', '3e01b52c-23e6-4474-872f-0609ce637f18', 3, 'Secondary failure: template render failed', 'A second error signature "template_render_failed" appears in the window; it may be a separate issue or a downstream effect.', 'low', 3.0, 0, '[]', '["Whether this error is related to the primary failure"]', '[{"step":"Check whether \"template_render_failed\" also occurs outside the incident window.","why":"Distinguishes a pre-existing issue from part of this incident.","expected_signal":"Occurrences only within the incident window."}]');

