INSERT INTO "rca_drafts" ("id", "incident_id", "investigation_id", "version", "status", "impact", "timeline", "root_cause", "contributing_factors", "resolution_steps", "prevention_actions", "evidence_ids", "generated_at", "updated_at", "validation_issues", "llm_mode") VALUES ('b3d21f5e-8bec-4328-91b2-8d66d4fdf258', 'd9202e95-90a2-54a9-aead-bfb7159ef028', '3d0ac2cf-7265-4228-8169-2b54160cb14c', 1, 'reviewed', '~28% of payment requests failing; checkout conversion down sharply for all regions. Severity SEV-1 in production.', '[{"timestamp":"2026-10-27T10:00:00Z","event":"payment-api v2.8.1 rollout started","evidence_ids":["tl:5bda604c-80f5-59dd-aa7b-fcfcb939cb98"]},{"timestamp":"2026-10-27T10:03:50Z","event":"First HTTP 500 responses returned to checkout","evidence_ids":["tl:8bb123fa-8cf0-5570-ada3-ebd3cafd09f9"]},{"timestamp":"2026-10-27T10:04:12Z","event":"First error logged: ERROR payment-api: database connection acquisition timed out; request_id=req-781 [signature=db_conn_acquire_timeout]","evidence_ids":["log:7ef1ad9b-c7cd-5c68-ab5a-85252c539ef5"]},{"timestamp":"2026-10-27T10:05:00Z","event":"Alert fired: payment-api 5xx rate above 5% for 1 minute","evidence_ids":["tl:2b46c01b-4e6e-573d-a0ee-2828f65c2af0"]},{"timestamp":"2026-10-27T10:07:00Z","event":"On-call engineer acknowledged the page","evidence_ids":["tl:a57f0077-b88d-5a73-a7b7-f95c93b3586b"]},{"timestamp":"2026-10-27T10:12:00Z","event":"Incident declared SEV-1; incident commander assigned","evidence_ids":["tl:90831ecf-7cb0-5cae-a7ba-741db105e791"]}]', 'Verified by engineer: payment-api v2.8.1 moved pool settings to db-client.yaml and set pool.max=20 (was 100), exhausting the pool at normal load.', '["Considered: Load increase from the checkout-web v5.2.0 release (low confidence)","Considered: payments-db unavailable or overloaded (low confidence)","Engineer note: Matches what we saw on the pods."]', '["Validate the leading hypothesis: v2.8.1 config change reduced the DB connection pool (100 → 20), exhausting it under normal load.","Record the verified cause and the action taken in this report before closing the incident."]', '["Revisit the prevention actions from INC-0881: Validated config and restored last-known-good setting.","Add an alert on the leading error signature so recurrence is detected earlier."]', '["tl:5bda604c-80f5-59dd-aa7b-fcfcb939cb98","tl:8bb123fa-8cf0-5570-ada3-ebd3cafd09f9","log:7ef1ad9b-c7cd-5c68-ab5a-85252c539ef5","tl:2b46c01b-4e6e-573d-a0ee-2828f65c2af0","tl:a57f0077-b88d-5a73-a7b7-f95c93b3586b","tl:90831ecf-7cb0-5cae-a7ba-741db105e791"]', '2026-11-02T06:53:36.902Z', '2026-11-02T06:53:36.910Z', '[]', 'recorded');

